  "sql": "WITH _base AS (\n  SELECT\n    regions.name AS \"customers.regions.name\",\n    CAST(SUM(customers.credit) AS DOUBLE) AS \"customers.credit_total\"\n  FROM customers AS customers\n  LEFT JOIN regions AS regions\n    ON customers.region_id = regions.id\n  GROUP BY\n    regions.name\n), _cm_customers__orders__amount_sum AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.amount_sum\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  GROUP BY\n    customers__regions.name\n), base AS (\n  SELECT\n    _base.\"customers.regions.name\",\n    _cm_customers__orders__amount_sum.\"orders.amount_sum\" AS \"customers.revenue\",\n    _base.\"customers.credit_total\"\n  FROM _base\n  LEFT JOIN _cm_customers__orders__amount_sum\n    ON _base.\"customers.regions.name\" IS NOT DISTINCT FROM _cm_customers__orders__amount_sum.\"orders.customers.regions.name\"\n), step1 AS (\n  SELECT\n    \"customers.regions.name\",\n    \"customers.credit_total\",\n    \"customers.revenue\",\n    CASE\n      WHEN \"customers.revenue\" IS NULL\n      THEN NULL\n      ELSE RANK() OVER (\n        PARTITION BY CASE WHEN \"customers.revenue\" IS NULL THEN 1 ELSE 0 END\n        ORDER BY \"customers.revenue\" DESC\n      )\n    END AS \"customers.rank\"\n  FROM base\n)\nSELECT\n  \"customers.regions.name\",\n  \"customers.revenue\",\n  \"customers.rank\",\n  \"customers.credit_total\"\nFROM (\n  SELECT\n    \"customers.regions.name\",\n    \"customers.credit_total\",\n    \"customers.revenue\",\n    \"customers.rank\"\n  FROM step1\n) AS _outer\nORDER BY\n  \"customers.regions.name\" ASC\nLIMIT 101"
